=== ConversationRow
import { relativeTime } from '../format';
import type { ConversationSummary } from '../types';

interface Props {
  conversation: ConversationSummary;
  selected: boolean;
  meSub: string;
  onSelect: () => void;
}

export function ConversationRow({ conversation, selected, meSub, onSelect }: Props) {
  const { contact, assignee, status, lastActivityAt, preview } = conversation;
  return (
    <li>
      <button className={`row${selected ? ' selected' : ''}`} onClick={onSelect} aria-current={selected}>
        <span className="row-top">
          <span className="contact">{contact}</span>
          <time dateTime={lastActivityAt}>{relativeTime(lastActivityAt)}</time>
        </span>
        <span className="preview">{preview}</span>
        <span className="row-badges">
          <span className={`badge${assignee === meSub ? ' mine' : ''}`}>
            {assignee ? (assignee === meSub ? 'You' : assignee) : 'Unassigned'}
          </span>
          {status === 'closed' && <span className="badge">Closed</span>}
        </span>
      </button>
    </li>
  );
}
=== MessageBubble
import { clockTime } from '../format';
import type { Message } from '../types';

export function MessageBubble({ message }: { message: Message }) {
  const outbound = message.direction === 'out';
  const failed = message.status === 'failed';
  return (
    <li className={`bubble ${outbound ? 'out' : 'in'}${failed ? ' failed' : ''}`}>
      <p className="bubble-text">{message.text}</p>
      <span className="bubble-meta">
        <time dateTime={message.at}>{clockTime(message.at)}</time>
        {outbound && message.status && <span className={`status status-${message.status}`}>{message.status}</span>}
      </span>
    </li>
  );
}
=== ThreadHeader
import type { ConversationInfo } from '../types';

interface Props {
  contact: string;
  conversation: ConversationInfo | null;
  meSub: string;
  isAdmin: boolean;
  busy: boolean;
  onClaim: () => void;
  onRelease: () => void;
  onToggleStatus: () => void;
}

export function ThreadHeader({ contact, conversation, meSub, isAdmin, busy, onClaim, onRelease, onToggleStatus }: Props) {
  const assignee = conversation?.assignee ?? null;
  const closed = conversation?.status === 'closed';
  const heldByMe = assignee === meSub;
  const heldByOther = assignee !== null && !heldByMe;

  return (
    <header className="thread-header">
      <div>
        <h2>{contact}</h2>
        <p className="assignee">
          {assignee ? `Assigned to ${heldByMe ? 'you' : assignee}` : 'Unassigned'}
          {closed && ' (closed)'}
        </p>
      </div>
      <div className="actions">
        <button onClick={onClaim} disabled={busy || heldByMe || heldByOther}>
          {heldByOther ? `Held by ${assignee}` : 'Claim'}
        </button>
        {assignee && (heldByMe || isAdmin) && (
          <button onClick={onRelease} disabled={busy}>Release</button>
        )}
        <button onClick={onToggleStatus} disabled={busy}>{closed ? 'Reopen' : 'Close'}</button>
      </div>
    </header>
  );
}
=== ReplyBox
import { useState, type KeyboardEvent } from 'react';

const MAX_LENGTH = 4000;

export function ReplyBox({ onSend }: { onSend: (text: string) => void }) {
  const [text, setText] = useState('');
  const trimmed = text.trim();

  function send() {
    if (!trimmed) return;
    onSend(trimmed);
    setText('');
  }

  function onKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) {
      event.preventDefault();
      send();
    }
  }

  return (
    <form
      className="reply"
      onSubmit={(e) => {
        e.preventDefault();
        send();
      }}
    >
      <label htmlFor="reply-text" className="visually-hidden">Reply</label>
      <textarea
        id="reply-text"
        value={text}
        maxLength={MAX_LENGTH}
        rows={2}
        placeholder="Write a reply. Enter sends, Shift+Enter adds a line."
        onChange={(e) => setText(e.target.value)}
        onKeyDown={onKeyDown}
      />
      <button className="primary" type="submit" disabled={!trimmed}>Send</button>
    </form>
  );
}
=== Inbox
import { useCallback, useEffect, useRef, useState } from 'react';
import { errorText, get } from '../api';
import { useLatest } from '../useLatest';
import type { ConversationSummary, Frame, Me, Subscribe } from '../types';
import { ConversationRow } from './ConversationRow';
import { Banner } from './Banner';

type Filter = 'open' | 'closed' | 'mine';

const FILTERS: { id: Filter; label: string }[] = [
  { id: 'open', label: 'Open' },
  { id: 'closed', label: 'Closed' },
  { id: 'mine', label: 'Mine' },
];

interface Page {
  conversations: ConversationSummary[];
  next: string | null;
}

interface Props {
  me: Me;
  workspace: string;
  selected: string | null;
  onSelect: (contact: string) => void;
  subscribe: Subscribe;
  epoch: number;
}

export function Inbox({ me, workspace, selected, onSelect, subscribe, epoch }: Props) {
  const [filter, setFilter] = useState<Filter>('open');
  const [items, setItems] = useState<ConversationSummary[]>([]);
  const [next, setNext] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const requestId = useRef(0);

  const query = useCallback(
    (before?: string) => {
      const params = new URLSearchParams({ workspace, limit: '30' });
      if (filter === 'mine') {
        params.set('assignee', 'me');
      } else {
        params.set('status', filter);
      }
      if (before) params.set('before', before);
      return get<Page>(`/api/conversations?${params}`);
    },
    [workspace, filter],
  );

  const loadFirstPage = useCallback(async () => {
    const id = ++requestId.current;
    try {
      const page = await query();
      if (id !== requestId.current) return;
      setItems(page.conversations);
      setNext(page.next);
      setError(null);
    } catch (err) {
      if (id === requestId.current) setError(errorText(err));
    } finally {
      if (id === requestId.current) setLoading(false);
    }
  }, [query]);

  useEffect(() => {
    setLoading(true);
    loadFirstPage();
    return () => {
      requestId.current++;
    };
  }, [loadFirstPage]);

  // a (re)connected socket may have skipped frames, so reload the list
  useEffect(() => {
    if (epoch > 0) loadFirstPage();
  }, [epoch]);

  async function loadMore() {
    if (!next) return;
    const id = requestId.current;
    try {
      const page = await query(next);
      if (id !== requestId.current) return;
      setItems((current) => {
        const known = new Set(current.map((c) => c.contact));
        return [...current, ...page.conversations.filter((c) => !known.has(c.contact))];
      });
      setNext(page.next);
    } catch (err) {
      setError(errorText(err));
    }
  }

  const itemsRef = useLatest(items);
  const handleFrame = useLatest((frame: Frame) => {
    const known = itemsRef.current.some((c) => c.contact === frame.contact);
    if (!known) {
      loadFirstPage();
      return;
    }
    setItems((current) => applyFrame(current, frame, filter, me.sub));
  });

  useEffect(() => subscribe((frame) => handleFrame.current(frame)), [subscribe, handleFrame]);

  return (
    <nav className="inbox" aria-label="Inbox">
      <div className="tabs" role="group" aria-label="Filter conversations">
        {FILTERS.map((f) => (
          <button key={f.id} className="tab" aria-pressed={filter === f.id} onClick={() => setFilter(f.id)}>
            {f.label}
          </button>
        ))}
      </div>
      {error && <Banner>{error}</Banner>}
      {loading ? (
        <p className="empty" role="status">Loading...</p>
      ) : items.length === 0 && !error ? (
        <p className="empty">No conversations yet.</p>
      ) : (
        <ul className="rows">
          {items.map((c) => (
            <ConversationRow
              key={c.contact}
              conversation={c}
              selected={c.contact === selected}
              meSub={me.sub}
              onSelect={() => onSelect(c.contact)}
            />
          ))}
        </ul>
      )}
      {next && !loading && <button className="load-more" onClick={loadMore}>Load more</button>}
    </nav>
  );
}

function applyFrame(
  list: ConversationSummary[],
  frame: Frame,
  filter: Filter,
  meSub: string,
): ConversationSummary[] {
  const index = list.findIndex((c) => c.contact === frame.contact);
  if (index === -1) return list;
  const current = list[index];

  switch (frame.type) {
    case 'message.inbound':
      return moveToTop(list, index, { preview: frame.text, lastActivityAt: frame.occurred_at });
    case 'message.outbound':
      return moveToTop(list, index, { preview: frame.text, lastActivityAt: new Date().toISOString() });
    case 'message.status':
    case 'note.added':
      return list;
    case 'conversation.assigned': {
      if (filter === 'mine' && frame.assignee !== meSub) return list.filter((_, i) => i !== index);
      return replaceAt(list, index, { ...current, assignee: frame.assignee });
    }
    case 'conversation.status': {
      const stillShown = filter === 'mine' || frame.status === filter;
      if (!stillShown) return list.filter((_, i) => i !== index);
      return replaceAt(list, index, { ...current, status: frame.status });
    }
  }
}

function replaceAt(list: ConversationSummary[], index: number, item: ConversationSummary) {
  return list.map((c, i) => (i === index ? item : c));
}

function moveToTop(list: ConversationSummary[], index: number, changes: Partial<ConversationSummary>) {
  const updated = { ...list[index], ...changes };
  return [updated, ...list.filter((_, i) => i !== index)];
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { ApiError, conversationPath, errorText, get, post } from '../api';
import { useLatest } from '../useLatest';
import { addMessage, setStatus } from '../messages';
import type { ConversationInfo, Frame, Me, Message, Subscribe } from '../types';
import { MessageBubble } from './MessageBubble';
import { ReplyBox } from './ReplyBox';
import { ThreadHeader } from './ThreadHeader';
import { Banner } from './Banner';
import { NotesPanel } from './NotesPanel';

interface Props {
  me: Me;
  workspace: string;
  contact: string;
  isAdmin: boolean;
  subscribe: Subscribe;
  epoch: number;
}

interface MessagePage {
  conversation: ConversationInfo | null;
  messages: Message[];
  older: string | null;
}

const NEAR_BOTTOM = 80;

export function Thread({ me, workspace, contact, isAdmin, subscribe, epoch }: Props) {
  const [conversation, setConversation] = useState<ConversationInfo | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [older, setOlder] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const scroller = useRef<HTMLDivElement>(null);
  const stickToBottom = useRef(true);
  const heightBeforePrepend = useRef<number | null>(null);

  const fetchPage = useCallback(
    (before?: string) => {
      const params = new URLSearchParams({ workspace, limit: '50' });
      if (before) params.set('before', before);
      return get<MessagePage>(`${conversationPath(contact, '/messages')}?${params}`);
    },
    [workspace, contact],
  );

  useEffect(() => {
    let cancelled = false;
    fetchPage()
      .then((page) => {
        if (cancelled) return;
        setConversation(page.conversation);
        setMessages(page.messages);
        setOlder(page.older);
      })
      .catch((err) => !cancelled && setError(errorText(err)))
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [fetchPage]);

  useEffect(() => {
    if (epoch === 0) return;
    fetchPage()
      .then((page) => {
        setConversation(page.conversation);
        setMessages((current) => page.messages.reduce(addMessage, current));
      })
      .catch((err) => setError(errorText(err)));
  }, [epoch]);

  async function refreshConversation() {
    try {
      const page = await fetchPage();
      setConversation(page.conversation);
    } catch (err) {
      setError(errorText(err));
    }
  }

  async function loadEarlier() {
    if (!older) return;
    try {
      const page = await fetchPage(older);
      heightBeforePrepend.current = scroller.current?.scrollHeight ?? null;
      setMessages((current) => {
        const known = new Set(current.map((m) => `${m.direction}:${m.id}`));
        return [...page.messages.filter((m) => !known.has(`${m.direction}:${m.id}`)), ...current];
      });
      setOlder(page.older);
    } catch (err) {
      setError(errorText(err));
    }
  }

  useLayoutEffect(() => {
    const el = scroller.current;
    if (!el) return;
    if (heightBeforePrepend.current !== null) {
      el.scrollTop += el.scrollHeight - heightBeforePrepend.current;
      heightBeforePrepend.current = null;
    } else if (stickToBottom.current) {
      el.scrollTop = el.scrollHeight;
    }
  }, [messages, loading]);

  function onScroll() {
    const el = scroller.current;
    if (!el) return;
    stickToBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < NEAR_BOTTOM;
  }

  const handleFrame = useLatest((frame: Frame) => {
    if (frame.contact !== contact) return;
    switch (frame.type) {
      case 'message.inbound':
        setMessages((current) =>
          addMessage(current, { direction: 'in', id: frame.message_id, text: frame.text, at: frame.occurred_at }),
        );
        break;
      case 'message.outbound':
        setMessages((current) =>
          addMessage(current, {
            direction: 'out',
            id: frame.client_ref,
            text: frame.text,
            at: new Date().toISOString(),
            status: frame.status,
            sender: frame.sender,
          }),
        );
        break;
      case 'message.status':
        setMessages((current) => setStatus(current, frame.client_ref, frame.status));
        break;
      case 'conversation.assigned':
        setConversation((c) => ({ contact, status: 'open', ...c, assignee: frame.assignee }));
        break;
      case 'conversation.status':
        setConversation((c) => ({ contact, assignee: null, ...c, status: frame.status }));
        break;
    }
  });

  useEffect(() => subscribe((frame) => handleFrame.current(frame)), [subscribe, handleFrame]);

  async function send(text: string) {
    const clientRef = crypto.randomUUID();
    const body = { workspace, text, clientRef };
    const path = conversationPath(contact, '/reply');
    stickToBottom.current = true;
    setMessages((current) =>
      addMessage(current, {
        direction: 'out',
        id: clientRef,
        text,
        at: new Date().toISOString(),
        status: 'queued',
        sender: me.sub,
      }),
    );
    try {
      try {
        await post(path, body);
      } catch (err) {
        if (err instanceof ApiError) throw err;
        await post(path, body);
      }
    } catch {
      setMessages((current) => setStatus(current, clientRef, 'failed'));
    }
  }

  async function act(action: 'claim' | 'release' | 'close' | 'reopen') {
    setBusy(true);
    setError(null);
    try {
      await post(conversationPath(contact, `/${action}`), { workspace });
      if (action === 'claim') setConversation((c) => ({ contact, status: 'open', ...c, assignee: me.sub }));
      if (action === 'release') setConversation((c) => ({ contact, status: 'open', ...c, assignee: null }));
      if (action === 'close') setConversation((c) => ({ contact, assignee: null, ...c, status: 'closed' }));
      if (action === 'reopen') setConversation((c) => ({ contact, assignee: null, ...c, status: 'open' }));
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setError(action === 'claim' ? 'This conversation is already claimed by someone else.' : 'Someone else changed this conversation.');
        await refreshConversation();
      } else {
        setError(errorText(err));
      }
    } finally {
      setBusy(false);
    }
  }

  const closed = conversation?.status === 'closed';

  return (
    <section className="thread" aria-label={`Conversation with ${contact}`}>
      <ThreadHeader
        contact={contact}
        conversation={conversation}
        meSub={me.sub}
        isAdmin={isAdmin}
        busy={busy}
        onClaim={() => act('claim')}
        onRelease={() => act('release')}
        onToggleStatus={() => act(closed ? 'reopen' : 'close')}
      />
      {error && <Banner>{error}</Banner>}
      <NotesPanel meSub={me.sub} workspace={workspace} contact={contact} subscribe={subscribe} />
      <div className="messages" ref={scroller} onScroll={onScroll}>
        {older && <button className="load-more" onClick={loadEarlier}>Load earlier</button>}
        {loading ? (
          <p className="empty" role="status">Loading...</p>
        ) : messages.length === 0 ? (
          <p className="empty">No messages yet.</p>
        ) : (
          <ul className="bubbles">
            {messages.map((m) => (
              <MessageBubble key={`${m.direction}:${m.id}`} message={m} />
            ))}
          </ul>
        )}
      </div>
      <ReplyBox onSend={send} />
    </section>
  );
}
import { useCallback, useEffect, useRef, useState } from 'react';
import { conversationPath, errorText, get, post } from '../api';
import { useLatest } from '../useLatest';
import { decryptNote, encryptNote, noteAad } from '../crypto';
import {
  createKeyring,
  ensureKeypair,
  fetchKeyState,
  keyringSupported,
  loadWorkspaceKey,
  shareWithPending,
  type LocalKeys,
} from '../keyring';
import type { Frame, NoteRecord, Subscribe } from '../types';
import { relativeTime } from '../format';

interface Props {
  meSub: string;
  workspace: string;
  contact: string;
  subscribe: Subscribe;
}

interface Note {
  id: string;
  author: string;
  at: string;
  text: string | null;
}

type Phase = 'loading' | 'waiting' | 'ready';

export function NotesPanel({ meSub, workspace, contact, subscribe }: Props) {
  const supported = keyringSupported();
  const [open, setOpen] = useState(false);
  const [phase, setPhase] = useState<Phase>('loading');
  const [notes, setNotes] = useState<Note[]>([]);
  const [draft, setDraft] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const keys = useRef<LocalKeys | null>(null);
  const workspaceKey = useRef<CryptoKey | null>(null);
  const loadId = useRef(0);

  const loadNotes = useCallback(async () => {
    const key = workspaceKey.current;
    if (!key) return;
    const id = ++loadId.current;
    const { notes: records } = await get<{ notes: NoteRecord[] }>(
      `${conversationPath(contact, '/notes')}?${new URLSearchParams({ workspace })}`,
    );
    const decoded = await Promise.all(
      records.map(async (r): Promise<Note> => {
        try {
          const text = await decryptNote(key, r.ciphertext, r.iv, noteAad(workspace, contact, r.author));
          return { id: r.id, author: r.author, at: r.createdAt, text };
        } catch {
          return { id: r.id, author: r.author, at: r.createdAt, text: null };
        }
      }),
    );
    if (id === loadId.current) setNotes(decoded);
  }, [workspace, contact]);

  const sync = useCallback(async () => {
    keys.current ??= await ensureKeypair(meSub, workspace);
    const local = keys.current;
    let state = await fetchKeyState(workspace);
    let key = await loadWorkspaceKey(meSub, workspace, local, state);
    if (!key && !state.initialised) {
      await createKeyring(meSub, workspace, local);
      state = await fetchKeyState(workspace);
      key = await loadWorkspaceKey(meSub, workspace, local, state);
    }
    if (!key) {
      setPhase('waiting');
      return;
    }
    const first = !workspaceKey.current;
    workspaceKey.current = key;
    await shareWithPending(meSub, workspace, local, key, state);
    setPhase('ready');
    if (first) await loadNotes();
  }, [meSub, workspace, loadNotes]);

  useEffect(() => {
    if (!open || !supported) return;
    let stopped = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    async function tick() {
      try {
        await sync();
        setError(null);
      } catch (err) {
        if (!stopped) setError(errorText(err));
      }
      if (!stopped) timer = setTimeout(tick, workspaceKey.current ? 10000 : 5000);
    }
    tick();
    return () => {
      stopped = true;
      clearTimeout(timer);
    };
  }, [open, supported, sync]);

  const handleFrame = useLatest((frame: Frame) => {
    if (frame.type !== 'note.added' || frame.contact !== contact || !workspaceKey.current) return;
    loadNotes().catch((err) => setError(errorText(err)));
  });

  useEffect(() => subscribe((frame) => handleFrame.current(frame)), [subscribe, handleFrame]);

  async function addNote() {
    const key = workspaceKey.current;
    const text = draft.trim();
    if (!key || !text) return;
    setBusy(true);
    setError(null);
    try {
      const body = await encryptNote(key, text, noteAad(workspace, contact, meSub));
      await post(conversationPath(contact, '/notes'), { workspace, ...body });
      setDraft('');
      await loadNotes();
    } catch (err) {
      setError(errorText(err));
    } finally {
      setBusy(false);
    }
  }

  function body() {
    if (!supported) {
      return <p className="notes-hint">Private notes need IndexedDB and WebCrypto, which are only available in a secure context (HTTPS or localhost).</p>;
    }
    if (phase === 'loading') return <p className="notes-hint" role="status">Setting up encryption...</p>;
    if (phase === 'waiting') return <p className="notes-hint" role="status">Waiting for a teammate to share the workspace key.</p>;
    return (
      <>
        {notes.length === 0 ? (
          <p className="notes-hint">No notes yet.</p>
        ) : (
          <ul className="notes-list">
            {notes.map((n) => (
              <li key={n.id} className={n.text === null ? 'note undecryptable' : 'note'}>
                <p className="note-text">{n.text ?? 'Could not decrypt this note'}</p>
                <div className="note-meta">
                  {n.author === meSub ? 'You' : n.author} · {relativeTime(n.at)}
                </div>
              </li>
            ))}
          </ul>
        )}
        <form
          className="notes-compose"
          onSubmit={(e) => {
            e.preventDefault();
            addNote();
          }}
        >
          <textarea
            aria-label="New private note"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Write a private note"
          />
          <button className="primary" disabled={busy || !draft.trim()}>Add note</button>
        </form>
      </>
    );
  }

  return (
    <section className="notes" aria-label="Private notes">
      <button className="notes-toggle" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        Private notes {open ? '(hide)' : '(show)'}
      </button>
      {open && (
        <>
          <p className="notes-hint">End-to-end encrypted. Only agents in this workspace can read these notes, not the server.</p>
          {error && <p className="notes-hint" role="alert">{error}</p>}
          {body()}
        </>
      )}
    </section>
  );
}
